//! Every setting in Preferences' panels, for the command palette:
//! made by Preferences' `ui_lint_settings_index` test from the panels as
//! they're drawn (`OLO_WRITE_SETTINGS=1 cargo ui-lint` writes it again).
//! Not edited by hand.

/// A control in a panel: the panel's argument (`apps::PREFERENCE_PANELS`),
/// the tab it's on and the box it's in (empty: none), its name as shown,
/// and what kind of control it is (AccessKit's role).
pub struct Setting {
    pub panel: &'static str,
    pub tab: &'static str,
    pub group: &'static str,
    pub name: &'static str,
    pub role: &'static str,
}

